def topo_sort(graph):
    in_degree = {node: 0 for node in graph}
    for node in graph:
        for prereq in graph[node]:
            if prereq not in in_degree:
                in_degree[prereq] = 0
            in_degree[prereq] += 1

    ready = sorted([n for n in in_degree if in_degree[n] == 0])
    result = []

    while ready:
        node = ready.pop(0)
        result.append(node)
        for neighbor in graph.get(node, []):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                # Insert neighbor into sorted position
                import bisect
                bisect.insort(ready, neighbor)

    if len(result) != len(in_degree):
        raise ValueError("Cycle detected")

    return result
